mapper.sql:
WHERE p.status = 'ACTIVE'
AND p.name LIKE CONCAT( '%', TRIM(#{condition.keyword}), '%' )
AND p.product_type = #{condition.type}
AND p.base_price >= #{condition.minPrice}
AND p.base_price <= #{condition.maxPrice}
AND ( p.stock_quantity IS NULL OR p.stock_quantity > 0 )
AND p.stock_quantity = 0

mapper.update:
UPDATE products
SET stock_quantity = stock_quantity - #{quantity}
WHERE id = #{productId}
  AND product_type = 'GENERAL'
  AND status = 'ACTIVE'
  AND stock_quantity IS NOT NULL
  AND stock_quantity
       >= 
      #{quantity}

UPDATE products
SET stock_quantity = stock_quantity + #{quantity}
WHERE id = #{productId}
  AND stock_quantity IS NOT NULL

mapper.select:
SELECT EXISTS (
    SELECT 1
    FROM product_option_groups pog
    WHERE pog.id = #{optionGroupId}
      AND pog.product_id = #{productId}
)

SELECT EXISTS (
    SELECT 1
    FROM product_options po
    INNER JOIN product_option_groups pog
            ON pog.id = po.option_group_id
    WHERE po.id = #{optionId}
      AND po.option_group_id = #{optionGroupId}
      AND pog.product_id = #{productId}
)

mapper.update:
UPDATE product_option_groups
SET
    name = #{optionGroup.name},
    required = #{optionGroup.required},
    selection_type = #{optionGroup.selectionType},
    status = #{optionGroup.status}
WHERE id = #{optionGroup.id}
  AND product_id = #{productId}

UPDATE product_option_groups
SET sort_order = #{sortOrder}
WHERE id = #{optionGroupId}
  AND product_id = #{productId}

UPDATE product_options po
INNER JOIN product_option_groups pog
        ON pog.id = po.option_group_id
SET
    po.name = #{option.name},
    po.additional_price = #{option.additionalPrice},
    po.status = #{option.status}
WHERE po.id = #{option.id}
  AND po.option_group_id = #{optionGroupId}
  AND pog.product_id = #{productId}

UPDATE product_options po
INNER JOIN product_option_groups pog
        ON pog.id = po.option_group_id
SET po.sort_order = #{sortOrder}
WHERE po.id = #{optionId}
  AND po.option_group_id = #{optionGroupId}
  AND pog.product_id = #{productId}

mapper.sql:
WHERE 1 = 1
AND p.name LIKE CONCAT( '%', TRIM(#{condition.keyword}), '%' )
AND p.product_type = #{condition.type}
AND p.status = #{condition.status}
AND ( p.stock_quantity IS NULL OR p.stock_quantity > 0 )
AND p.stock_quantity = 0

mapper.select:
SELECT p.id, p.name, p.product_type AS productType, p.base_price AS basePrice, p.stock_quantity AS stockQuantity, p.status, p.created_at AS createdAt FROM products p
ORDER BY p.created_at DESC, p.id DESC
LIMIT #{size} OFFSET #{offset}

